<script lang="ts">
  import { onMount } from 'svelte';
  import { defaults, type Settings } from './types';
  import { settings, saveSettings } from './storage';
  import { engine } from './runtime';
  import { localUrl,translationInstructionsLimit } from './core';
  import lock from './model-lock.json';
  import { googleWebOrigin } from './google-web';
  import { prepareChromeTranslator,disposeChromeTranslator,chromeTranslatorAvailability } from './chrome-translator';
  import {extensionCall,detached} from './extension-context';
  import {buildId} from './build-info';
  import {geminiOrigin} from './gemini-web';
  let config = $state<Settings>({ ...defaults }), message = $state(''), busy = $state(false), origin = $state(''), error = $state('');
  let gpu = $state<any>(),siteGrants=$state<string[]>([]);
  const mangaGrant=(p:string)=>/^https?:\/\//.test(p)&&!p.includes('googleapis.com')&&!p.includes('gemini.google.com')&&!p.includes('huggingface.co')&&!p.includes('.hf.co')&&!p.includes('127.0.0.1')&&!p.includes('localhost');
  async function readGrants(){siteGrants=(await chrome.permissions.getAll()).origins?.filter(mangaGrant)??[];}
  function selectSite(site:string,on:boolean){config.autoSites=on?[...new Set([...(config.autoSites??[]),site])]:(config.autoSites??[]).filter(s=>s!==site);}
  let nativeState=$state('尚未檢查');
  let geminiState=$state<any>(),geminiRunning=$state(false),geminiProgress=$state('');
  onMount(()=>{detached(async()=>{geminiState=(await chrome.storage.local.get('geminiValidation')).geminiValidation;});const changed=(changes:Record<string,chrome.storage.StorageChange>)=>{if(changes.geminiValidationProgress){const progress=changes.geminiValidationProgress.newValue as any;geminiProgress=`${progress.completed}/30 批 · ${progress.phase??'核對區域 ID 完成'}`;message='匿名 Gemini：'+geminiProgress;}};chrome.storage.onChanged.addListener(changed);return()=>chrome.storage.onChanged.removeListener(changed);});
  async function unlockGemini(){if(!confirm('先前匿名請求的結果可能已產生。解除鎖定後，再次翻譯會建立新請求；確定繼續？'))return;try{const r=await chrome.runtime.sendMessage({channel:'gemini-unlock'});if(!r?.ok)throw new Error(r?.error);message='已人工解除結果未知鎖定。';}catch(e){error=String(e);}}
  async function prepareRefinement(){if(geminiState?.status!=='passed'){await validateGemini();return;}try{if(!await chrome.permissions.request({origins:[geminiOrigin]}))throw new Error('Gemini 網站權限未核准');message='整章 Gemini 校正已就緒；Google 初譯完成後送出整章文字，無需重跑 30 批協定測試。';error='';}catch(e){error=String(e);}}
  async function validateGemini(){if(busy)return;busy=true;geminiRunning=true;geminiState=undefined;geminiProgress='準備權限與匿名初始化';error='';try{if(!await chrome.permissions.request({origins:[geminiOrigin]}))throw new Error('Gemini 網站權限未核准');message='開始匿名短句與 30 批格式驗證；遇到阻擋立即停止。';const response=await extensionCall(()=>chrome.runtime.sendMessage({channel:'gemini-validate'}));if(!response?.ok)throw new Error(response?.error??'匿名驗證未回應');geminiState=response.result;message=geminiState.status==='passed'?'匿名協定通過 30 批；可選用實驗來源，翻譯品質仍需人工覆核。':`匿名路線受阻：${geminiState.error}（完成 ${geminiState.completed}/30 批）`;}catch(e){error=String(e);}finally{busy=false;geminiRunning=false;}}
  onMount(() => { detached(async()=>{config=await settings();await readGrants();},e=>{error=String(e);});addEventListener('pagehide',disposeChromeTranslator);return ()=>{removeEventListener('pagehide',disposeChromeTranslator);disposeChromeTranslator();}; });
  async function probeGpu(){if(busy)return;busy=true;error='';try{gpu=await engine({op:'probe',refresh:true});message=gpu.available?'WebGPU 可用':gpu.reason;}catch(e){error=String(e);}finally{busy=false;}}
  const nativeLabels={unavailable:'未支援',downloadable:'待下載',downloading:'下載中',available:'就緒'};
  async function checkNative(){if(busy)return;busy=true;error='';try{const state=await chromeTranslatorAvailability();nativeState=nativeLabels[state.status]+(state.reason?` · ${state.reason}`:'');const response=await extensionCall(()=>chrome.runtime.sendMessage({channel:'native-status'}));message=response?.ok?`推論文件：${nativeLabels[response.result.status as keyof typeof nativeLabels]}`:response?.error;}catch(e){error=String(e);}finally{busy=false;}}
  async function prepareNative(){if(busy)return;busy=true;error='';try{await prepareChromeTranslator(d=>message=d.message);nativeState='就緒';const response=await extensionCall(()=>chrome.runtime.sendMessage({channel:'native-status'}));message=response?.ok&&response.result.status==='available'?'Chrome 本機翻譯語言包及推論文件已就緒。':'可見設定頁已就緒；推論文件尚未就緒，請檢查狀態或選其他來源。';}catch(e){error=String(e);const state=await chromeTranslatorAvailability();nativeState=nativeLabels[state.status];}finally{disposeChromeTranslator();busy=false;}}
  async function save() {
    error = ''; try { if (config.backend === 'google-web' && !await chrome.permissions.request({ origins: [googleWebOrigin] })) throw new Error('Google 文字請求權限未核准');if(config.backend==='gemini-web'&&geminiState?.status!=='passed')throw new Error('匿名 Gemini 尚未通過實測'); localUrl(config.endpoint); localUrl(config.ocrEndpoint); if(['webllm','google-web'].includes(config.backend)&&config.localFallback&&!config.localModel.trim())throw new Error('啟用備援前，請填入本機模型名稱');if(config.auto&&!config.autoSites?.length)throw new Error('請勾選要自動啟用的漫畫網站'); await saveSettings($state.snapshot(config)); message = '設定已儲存。新工作台與下次頁面啟用時生效；執行中的模型會在閒置釋放後套用新執行緒。'; } catch (e) { error = String(e); }
  }
  async function prefetch() {
    if (busy) return; busy = true; error = '';
    try { if(config.backend==='webllm')gpu=await engine({op:'probe'}); const modelId = config.backend === 'webllm' ? `Qwen3.5-${config.model === '2b' ? '2B' : '0.8B'}-q4f${gpu?.f16 ? '16' : '32'}_1-MLC` : ''; await engine({ op: 'prefetch', modelId }, d => message = d.message); message = ['google-web','gemini-web'].includes(config.backend) ? 'OCR 模型下載完成。Google／Gemini 網頁翻譯需連線；離線翻譯請選本機模式。' : config.backend==='chrome' ? 'OCR 模型下載完成；Chrome 翻譯語言包由工作台的翻譯按鈕另行取得。' : '模型下載完成，可執行離線驗證。'; }
    catch (e) { error = String(e); } finally { busy = false; }
  }
  async function grant() {
    try { const url = new URL(origin); if (!['https:', 'http:'].includes(url.protocol)) throw new Error('請輸入 HTTP(S) 網址'); const ok = await chrome.permissions.request({ origins: [`${url.origin}/*`] }); if(ok)await readGrants(); message = ok ? '網站已授權，請重新整理漫畫頁。圖片 CDN 可另外授權。' : '網站授權未核准'; } catch (e) { error = String(e); }
  }
  function clearCache(){void chrome.tabs.create({url:chrome.runtime.getURL('/cache.html')});}
</script>
<main><a href="reader.html">← 漫畫工作台</a> · <a href="cache.html">快取與推論資源</a><h1>墨譯 · 模型與閱讀設定</h1><small>0.1.12 · 建置 {buildId}</small><p>日文 → 臺灣繁體中文。瀏覽器模型下載後在本機執行。</p>
  <section><h2>初譯來源</h2><label>執行方式<select bind:value={config.backend}><option value="google-web">Google 網頁翻譯 · 免金鑰、零 API 費</option><option value="chrome">Chrome Translator API · 本機、零 API 費</option><option value="webllm">瀏覽器 WebGPU · WebLLM</option><option value="local">本機 OpenAI-compatible 服務</option></select></label>
  {#if config.backend==='gemini-web'}<p class="hint">僅傳送日文文字、術語與前頁摘要；所有請求省略帳號憑證。網站自動選模型，提交後斷線會保存結果未知狀態並停止。</p>{/if}
  {#if config.backend === 'google-web'}<p class="hint">OCR 後的日文文字會傳給 Google；漫畫圖片留在本機。不需帳號、金鑰或 Cloud 帳務。此為非官方網頁介面，可能限流或改版；遇到錯誤即停止。人物術語、上下文與專屬指示用於後續 Gemini 整章校正或本機模型翻譯。</p>{/if}
  {#if config.backend === 'chrome'}<p class="hint">Chrome 的專用翻譯模型在本機執行，不需 Cloud 金鑰或帳務。首次下載語言包；可用性依瀏覽器與語言對確認。日文 → 繁中：{nativeState}</p><button disabled={busy} onclick={prepareNative}>準備 Chrome 本機翻譯</button><button disabled={busy} onclick={checkNative}>檢查 Chrome 本機翻譯</button>{/if}
  {#if config.backend === 'webllm'}<label>模型<select bind:value={config.model}><option value="2b">Qwen3.5 2B Q4 · 品質候選</option><option value="0.8b">Qwen3.5 0.8B Q4 · 低資源候選</option></select></label><p class="hint">WebGPU：{gpu?.available ? '可用' : '尚未確認／不可用'}；shader-f16：{gpu?.f16 ? '支援' : '使用 f32 候選'}。模型品質尚待真實漫畫人工驗收。</p><button disabled={busy} onclick={probeGpu}>檢查 WebGPU</button>{/if}
  {#if ['webllm','google-web'].includes(config.backend)}<label class="check"><input type="checkbox" bind:checked={config.localFallback}>翻譯來源失敗時，改用已設定的本機服務</label>{/if}
  {#if config.backend === 'local' || (['webllm','google-web'].includes(config.backend) && config.localFallback)}<label>本機 Base URL<input bind:value={config.endpoint} placeholder="http://127.0.0.1:8080/v1"></label><label>模型名稱<input bind:value={config.localModel} placeholder="例如 qwen3.5:2b"></label><button onclick={()=>{config.endpoint='http://127.0.0.1:8767/v1';config.localModel='qwen3.5-2b';}}>填入本專案 CPU 服務設定</button><p class="hint">可接 Ollama、llama-server、LM Studio，或本專案的 CPU 伴隨服務。僅接受 localhost；先啟動服務再使用。</p>{/if}
  <label>瀏覽器 OCR 後端<select bind:value={config.ocrProvider}><option value="wasm">WASM CPU（預設，省去 GPU 探測）</option><option value="auto">WebGPU 優先，失敗時降級 WASM</option></select></label><label class="check"><input type="checkbox" bind:checked={config.localOcr}>使用獨立本機 ONNX OCR 服務</label>{#if config.localOcr}<label>OCR Base URL<input bind:value={config.ocrEndpoint}></label>{/if}</section>
  <section><h2>閱讀效能</h2><label>在途圖片<select aria-label="在途圖片" bind:value={config.pageConcurrency}><option value={2}>兩張流水線（共用一組 OCR）</option><option value={1}>一張串行（較低記憶體）</option></select></label><p class="hint">Google／Chrome／Gemini 模式可重疊下一張 OCR 與上一張翻譯；Google 請求仍依序處理。WebLLM／本機 LLM 維持單頁，保留上下文順序。資源錯誤會改為一張，續翻時生效。</p></section>
  <section><h2>WASM CPU 執行緒</h2><label>執行緒<select aria-label="WASM 執行緒" bind:value={config.wasmThreads}><option value="auto">自動（尚無合格量測時用 1）</option><option value={1}>1</option><option value={2}>2</option><option value={4}>4</option></select></label><p class="hint">需要跨來源隔離與 SharedArrayBuffer，否則降回 1。儲存後於下次模型釋放、重新建立時套用；實際 pthread 與降級原因可在快取與資源管理查看。</p></section>
  <section><h2>整章 Gemini 二段校正</h2><label class="check"><input type="checkbox" bind:checked={config.refineAfterChapter}>Google 完成本頁全部圖片後，自動執行整章校正</label><p class="hint">將整章每頁的日文原文、初譯與目前譯文一起送出，統一人名、語氣與上下文。完整核對回覆後逐張重排；Google 初譯保留於校正欄。最多 60 張、800 個可校正區域、120 KB 文字；超過上限保留初譯並提示。圖片維持本機，匿名請求省略帳號憑證。</p><p>狀態：{geminiRunning?'驗證進行中':geminiState?.status==='passed'?'協定已通過，可進行整章校正':geminiState?.status==='blocked'?`受阻（${geminiState.completed}/30）`:'尚未準備'}</p><button disabled={busy} onclick={prepareRefinement}>準備整章 Gemini 校正</button>{#if geminiRunning}<p role="status">{geminiProgress}</p>{/if}<details><summary>匿名協定診斷</summary><p class="hint">30 批是連線與格式測試，使用原創短句，與漫畫頁數及整章品質評分分開。已通過者不需重跑。診斷原文與回覆只存本機。</p><button disabled={busy} onclick={validateGemini}>重新驗證匿名協定（最多 30 批）</button><button disabled={busy} onclick={unlockGemini}>解除結果未知鎖定</button></details>{#if geminiState?.error}<p class="error">{geminiState.error}</p>{/if}</section>
  <section><h2>故事上下文</h2><p class="hint">人名、術語與前頁摘要用於 Gemini／Qwen／本機服務。Google 網頁與 Chrome 本機翻譯採逐框翻譯；譯文可在工作台直接校正。</p><label>作品名稱<input bind:value={config.title}></label><label>章節<input bind:value={config.chapter}></label><label>人名／術語表<textarea rows="4" bind:value={config.glossary} placeholder="例：葵＝小葵；先輩＝學長"></textarea></label><label>漫畫專屬翻譯指示<textarea aria-label="漫畫專屬翻譯指示" rows="5" maxlength={translationInstructionsLimit} bind:value={config.translationInstructions} placeholder="例：這部作品是奇幻喜劇；主角口氣直率，長老說話較正式。兄長稱呼統一為「哥哥」，保留吐槽語氣，避免中國大陸用語。"></textarea><small>{config.translationInstructions.length} / {translationInstructionsLimit} 字</small></label><p class="hint">補充本作品的語氣、稱呼與用詞偏好；套用於 Gemini 整章校正及 WebLLM／本機 LLM。固定 JSON 格式與文字框 ID 仍由插件管理。Google／Chrome 初譯維持逐框翻譯；修改後可直接重跑整章校正，沿用已存初譯。這些設定由本機保存，目前套用至所有漫畫；閱讀不同作品時可修改。</p><label>前頁摘要<textarea rows="3" bind:value={config.priorSummary}></textarea></label><label class="check"><input type="checkbox" bind:checked={config.auto}>在勾選網站自動翻譯可見漫畫圖片（依在途圖片設定處理）</label>{#if config.auto}{#each siteGrants as site}<label class="check"><input type="checkbox" checked={config.autoSites?.includes(site)??false} onchange={e=>selectSite(site,e.currentTarget.checked)}>{site}</label>{/each}{#if !siteGrants.length}<p>請先在下方授權漫畫網站，再勾選自動啟用。</p>{/if}{/if}</section>
  <section><h2>網站權限</h2><label>漫畫網站或圖片 CDN 網址<input bind:value={origin} placeholder="https://example.com"></label><button onclick={grant}>授權這個來源</button><p class="hint">只授權你需要的網站；授權後重新整理頁面。</p></section>
  <div class="actions"><button class="primary" onclick={save}>儲存設定</button><button disabled={busy} onclick={prefetch}>下載模型供離線使用</button><button disabled={busy} onclick={clearCache}>管理快取</button></div>
  {#if message}<p role="status">{message}</p>{/if}{#if error}<p class="error" role="alert">{error}</p>{/if}
  <details><summary>固定模型與授權清單</summary><pre>{JSON.stringify({ vision: lock.vision.map(m => ({ id: m.id, revision: m.revision, license: m.license })), llm: lock.llm.map(m => ({ id: m.model_id, revision: m.revision, licenseReview: m.convertedLicenseStatus })), font: lock.font }, null, 2)}</pre></details>
</main>
<style>:global(body){margin:0;background:#f1eee6;font:14px "Microsoft JhengHei",sans-serif;color:#293f32}main{max-width:800px;margin:auto;padding:36px}a{color:#355947}h1{font-size:27px}h2{font-size:18px}section{padding:22px;background:#fafbf7;border:1px solid #d3dbce;border-radius:10px;margin:18px 0}label{display:block;margin:15px 0;font-size:13px}input,select,textarea{box-sizing:border-box;width:100%;display:block;padding:10px;margin-top:7px;border:1px solid #cbd6c8;border-radius:5px;font:inherit;background:white;color:#293f32}.check{display:flex;align-items:center;gap:9px}.check input{width:17px;height:17px;margin:0}button{padding:10px 14px;border:1px solid #b9c7b9;background:#f9fbf5;border-radius:6px;font:inherit;cursor:pointer}.primary{background:#284e3c;color:white}button:disabled{opacity:.5}.hint{font-size:12px;color:#657a69;line-height:1.7}.actions{display:flex;gap:10px;flex-wrap:wrap}.error{color:#9b3823}pre{overflow:auto;font-size:11px}details{margin-top:28px}</style>
